// Princípios por matéria (resumos autorais de estudo — confira sempre o texto da lei/Constituição).
(function () {
  const ALL = ["oab", "magsc", "mpsc", "magfed"];
  const add = (materia, itens, mods) => itens.forEach(([nome, desc]) => DATA.principios.push({ materia, nome, desc, mods: mods || ALL }));

  add("Constitucional", [
    ["Supremacia da Constituição", "A Constituição é a norma fundamental; todo ato normativo deve com ela ser compatível, sob pena de inconstitucionalidade (controle de constitucionalidade)."],
    ["Soberania", "Fundamento da República (art. 1º, I, CF): poder supremo no plano interno e independência no plano externo."],
    ["Cidadania", "Fundamento da República (art. 1º, II): participação política e fruição dos direitos civis, políticos e sociais."],
    ["Valores sociais do trabalho e da livre iniciativa", "Fundamento da República (art. 1º, IV): equilíbrio entre proteção do trabalho e liberdade econômica."],
    ["Pluralismo político", "Fundamento da República (art. 1º, V): respeito à diversidade de ideias, partidos e correntes de pensamento."],
    ["Princípio democrático", "Todo o poder emana do povo (art. 1º, parágrafo único), exercido por representantes eleitos ou diretamente (plebiscito, referendo, iniciativa popular)."],
    ["Princípio republicano", "Eletividade, temporariedade e responsabilidade dos governantes; igualdade formal e prestação de contas."],
    ["Princípio federativo", "União indissolúvel de Estados, Municípios e Distrito Federal (art. 1º e 18); autonomia política, administrativa e financeira; cláusula pétrea (art. 60, §4º, I)."],
    ["Princípio do Estado de Direito", "Submissão de governantes e governados à lei e ao Direito; legalidade, separação de poderes e garantia de direitos."],
    ["Legalidade (art. 5º, II)", "Ninguém é obrigado a fazer ou deixar de fazer algo senão em virtude de lei."],
    ["Isonomia (igualdade)", "Art. 5º, caput: tratar igualmente os iguais e desigualmente os desiguais, na medida de sua desigualdade; admite discriminações razoáveis e ações afirmativas."],
    ["Inafastabilidade da jurisdição", "Art. 5º, XXXV: a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito. Admite exceções como a arbitragem voluntária e a exigência de esgotamento prévio na Justiça Desportiva (art. 217, §1º)."],
    ["Devido processo legal", "Art. 5º, LIV: ninguém será privado da liberdade ou de seus bens sem o devido processo legal, em suas faces formal (procedimento) e material (razoabilidade/proporcionalidade)."],
    ["Contraditório e ampla defesa", "Art. 5º, LV: direito de ser ouvido, de reagir e de usar os meios e recursos inerentes à defesa, em processo judicial ou administrativo."],
    ["Presunção de inocência (não culpabilidade)", "Art. 5º, LVII: ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória."],
    ["Juiz natural", "Art. 5º, XXXVII e LIII: vedados juízo ou tribunal de exceção; ninguém será processado nem sentenciado senão pela autoridade competente."],
    ["Razoabilidade e proporcionalidade", "Controle de excessos estatais pelas máximas da adequação, da necessidade (menor restrição possível) e da proporcionalidade em sentido estrito."],
    ["Máxima efetividade (eficácia integradora)", "Entre as interpretações possíveis, deve prevalecer a que confira maior eficácia à norma constitucional."],
    ["Unidade da Constituição", "A Constituição deve ser interpretada como um todo harmônico, evitando antinomias entre suas normas."],
    ["Concordância prática (harmonização)", "Em colisão de direitos fundamentais, busca-se a coordenação e a combinação dos bens jurídicos, evitando o sacrifício total de um deles."],
    ["Correção funcional (conformidade funcional)", "O intérprete não pode alterar a repartição de funções estabelecida pela Constituição entre os órgãos do Estado."],
    ["Força normativa da Constituição", "Deve-se preferir a interpretação que garanta eficácia e permanência às normas constitucionais."],
    ["Interpretação conforme a Constituição", "Entre vários sentidos possíveis da lei, adota-se o compatível com a Constituição, sem contrariar o texto (vedado criar norma nova)."],
    ["Presunção de constitucionalidade das leis", "As leis e atos do Poder Público presumem-se constitucionais até que se declare o contrário; a presunção é relativa."],
    ["Proibição de retrocesso", "Vedação à supressão ou redução injustificada de direitos fundamentais já concretizados."],
    ["Reserva do possível e mínimo existencial", "A efetivação de direitos sociais depende de recursos, mas não pode ser invocada para afastar o núcleo essencial (mínimo existencial)."],
    ["Separação dos Poderes", "Art. 2º: Legislativo, Executivo e Judiciário, independentes e harmônicos entre si; cláusula pétrea (art. 60, §4º, III)."],
    ["Simetria", "Os Estados e Municípios devem observar, em sua organização, os modelos básicos da Constituição Federal naquilo que for de reprodução obrigatória."],
    ["Princípio da anterioridade tributária", "Art. 150, III, «b» e «c»: tributos não podem ser cobrados no mesmo exercício da lei que os institui ou aumenta, nem antes de 90 dias (com exceções)."],
    ["Reserva de jurisdição (cláusula de reserva)", "Certas medidas só podem ser determinadas por juiz (ex.: interceptação telefônica, busca domiciliar em período noturno, prisão salvo flagrante)."],
    ["Publicidade dos atos processuais", "Art. 5º, LX e 93, IX: atos processuais públicos, salvo restrição por defesa da intimidade ou interesse social; decisões judiciais fundamentadas, sob pena de nulidade."],
    ["Dignidade da pessoa humana", "Art. 1º, III: fundamento da República; vetor interpretativo de todos os direitos fundamentais; veda a coisificação do indivíduo."],
  ]);

  add("Administrativo", [
    ["Legalidade administrativa", "Art. 37, caput: o administrador só pode fazer o que a lei autoriza (vinculação positiva); ao particular é permitido tudo o que a lei não proíbe."],
    ["Impessoalidade", "Atuação voltada ao interesse público, sem favorecimento ou perseguição; atos imputados ao órgão, não ao agente (art. 37, §1º)."],
    ["Moralidade", "Atuação conforme a ética, a probidade, a lealdade e a boa-fé; sua violação pode caracterizar improbidade (Lei 8.429/92)."],
    ["Publicidade", "Transparência dos atos administrativos, com ressalva do sigilo imprescindível à segurança da sociedade e do Estado; condição de eficácia dos atos."],
    ["Eficiência", "EC 19/98: busca de resultados com qualidade, celeridade e economicidade na gestão pública."],
    ["Supremacia do interesse público sobre o privado", "Em caso de conflito, o interesse da coletividade prevalece, respeitados os direitos fundamentais (ponderação)."],
    ["Indisponibilidade do interesse público", "O administrador não é dono do interesse público; não pode dispor dele sem autorização legal."],
    ["Autotutela", "A Administração pode anular seus atos ilegais e revogar os inconvenientes e inoportunos, sem necessidade de provocar o Judiciário (Súmulas 346 e 473 do STF)."],
    ["Continuidade do serviço público", "Os serviços públicos essenciais não podem ser interrompidos arbitrariamente; limita o direito de greve e a exceção do contrato não cumprido."],
    ["Segurança jurídica e proteção da confiança", "Proteção de situações consolidadas e da boa-fé do administrado; prazo decadencial de 5 anos para anular atos favoráveis (Lei 9.784/99, art. 54)."],
    ["Motivação", "Dever de indicar os fundamentos de fato e de direito das decisões (Lei 9.784/99, art. 50); teoria dos motivos determinantes."],
    ["Razoabilidade e proporcionalidade administrativas", "Adequação entre meios e fins, vedadas obrigações, restrições e sanções em medida superior à necessária (Lei 9.784/99, art. 2º)."],
    ["Finalidade", "O ato deve visar ao fim legal, que é sempre o interesse público; o desvio de finalidade gera nulidade."],
    ["Especialidade", "As entidades da Administração Indireta só podem atuar nos limites da finalidade para a qual foram criadas por lei."],
    ["Controle (tutela ou supervisão ministerial)", "A Administração Direta exerce controle finalístico sobre a Indireta, nos limites da lei, sem hierarquia."],
    ["Hierarquia", "Relação de coordenação e subordinação entre órgãos e agentes; poder de comandar, fiscalizar, rever, delegar e avocar."],
    ["Presunção de legitimidade dos atos administrativos", "Os atos presumem-se legais e verdadeiros até prova em contrário (presunção relativa)."],
    ["Concurso público", "Art. 37, II: a investidura em cargo ou emprego efetivo depende de aprovação prévia em concurso público, ressalvados os cargos em comissão."],
    ["Isonomia e proposta mais vantajosa (licitação)", "Licitação visa ao tratamento isonômico, à proposta mais vantajosa e ao desenvolvimento nacional sustentável (Lei 14.133/21, art. 11)."],
    ["Vinculação ao edital", "A Administração e os licitantes devem observar as regras do edital, que é a lei interna da licitação."],
    ["Julgamento objetivo", "A licitação deve ser julgada com base em critérios objetivos previstos no edital, afastando subjetivismos."],
    ["Competitividade", "Vedadas cláusulas que restrinjam indevidamente a participação de interessados no certame."],
    ["Planejamento (Lei 14.133/21)", "As contratações devem ser precedidas de planejamento, com estudos técnicos preliminares e matriz de riscos."],
    ["Responsabilidade objetiva do Estado", "Art. 37, §6º: pessoas jurídicas de direito público e privadas prestadoras de serviço público respondem pelos danos causados por seus agentes, assegurado o regresso em caso de dolo ou culpa."],
    ["Teoria do risco administrativo", "A responsabilidade estatal independe de culpa, mas admite excludentes (culpa exclusiva da vítima, caso fortuito, força maior, fato de terceiro)."],
    ["Devido processo legal administrativo", "Contraditório e ampla defesa em processos administrativos, inclusive sancionadores e disciplinares (Súmula Vinculante 5: falta de defesa técnica não ofende a Constituição)."],
    ["Oficialidade (impulso oficial)", "A Administração deve impulsionar o processo administrativo de ofício, independentemente de provocação das partes."],
    ["Informalismo moderado (formalismo moderado)", "Exigem-se apenas as formalidades essenciais à garantia dos direitos dos administrados (Lei 9.784/99, art. 2º, IX)."],
    ["Gratuidade do processo administrativo", "Em regra, vedada a cobrança de despesas processuais, salvo previsão legal (Lei 9.784/99, art. 2º, XI)."],
    ["Verdade material", "No processo administrativo busca-se a verdade real dos fatos, podendo a Administração valer-se de provas além das apresentadas pelas partes."],
    ["Inalienabilidade dos bens públicos", "Bens públicos só podem ser alienados após desafetação, observados os requisitos legais (art. 100 do CC e Lei 14.133/21)."],
    ["Imprescritibilidade dos bens públicos", "Bens públicos não se sujeitam a usucapião (arts. 183, §3º, e 191, parágrafo único, CF; Súmula 340 do STF)."],
    ["Subsidiariedade", "O Estado atua na atividade econômica apenas quando necessário aos imperativos da segurança nacional ou a relevante interesse coletivo (art. 173, CF)."],
    ["Transparência e publicidade ativa", "Lei de Acesso à Informação (Lei 12.527/11): publicidade é a regra, sigilo a exceção; dever de divulgar informações de interesse coletivo independentemente de requerimento."],
    ["Proporcionalidade na sanção administrativa", "A sanção deve guardar relação com a gravidade da infração e as circunstâncias do caso (LINDB, art. 22)."],
    ["Consequencialismo (LINDB, art. 20)", "Decisões administrativas, controladoras e judiciais não podem se basear em valores jurídicos abstratos sem considerar as consequências práticas."],
  ]);

  add("Civil", [
    ["Autonomia privada", "Liberdade de os particulares regerem suas relações jurídicas, dentro dos limites da lei, da ordem pública e dos bons costumes."],
    ["Boa-fé objetiva", "Dever de agir com lealdade, correção e probidade (arts. 113, 187 e 422, CC); gera deveres anexos de informação, cooperação e proteção; funções interpretativa, integrativa e limitadora."],
    ["Função social do contrato", "Art. 421, CC: a liberdade contratual será exercida em razão e nos limites da função social; relativiza a força obrigatória e protege terceiros."],
    ["Função social da propriedade", "Arts. 5º, XXIII, e 186, CF e art. 1.228, §1º, CC: a propriedade deve atender a finalidades econômicas, sociais, ambientais e culturais."],
    ["Força obrigatória dos contratos (pacta sunt servanda)", "Os contratos devem ser cumpridos conforme pactuado; mitigada pela revisão por onerosidade excessiva e pela função social."],
    ["Relatividade dos efeitos contratuais", "Em regra, o contrato produz efeitos apenas entre as partes; admite exceções (estipulação em favor de terceiro, tutela externa do crédito)."],
    ["Consensualismo", "A regra é que os contratos se aperfeiçoam com o simples acordo de vontades, sem formalidade especial (art. 107, CC)."],
    ["Equivalência material (equilíbrio contratual)", "Busca-se o equilíbrio entre prestação e contraprestação; fundamento da lesão, do estado de perigo e da revisão contratual (arts. 156, 157, 317 e 478, CC)."],
    ["Eticidade", "Um dos pilares do CC/2002: valorização da conduta ética e da boa-fé nas relações privadas."],
    ["Socialidade", "Pilar do CC/2002: prevalência dos valores coletivos sobre os individuais, sem perder o valor da pessoa."],
    ["Operabilidade (concretude)", "Pilar do CC/2002: soluções simples e efetivas, com cláusulas gerais e conceitos indeterminados que permitem a concretização pelo juiz."],
    ["Princípio da simetria (paralelismo) das formas", "O distrato deve observar a mesma forma exigida para o contrato (art. 472, CC)."],
    ["Conservação dos negócios jurídicos", "Preferência pela manutenção do negócio, aproveitando-se o que for possível (redução, conversão substancial, convalidação; arts. 170, 184 e 183, CC)."],
    ["Boa-fé na interpretação dos negócios", "Art. 113, CC: os negócios jurídicos devem ser interpretados conforme a boa-fé e os usos do lugar de sua celebração."],
    ["Vedação ao comportamento contraditório (venire contra factum proprium)", "Ninguém pode exercer direito em contradição com conduta anterior que gerou confiança legítima."],
    ["Supressio e surrectio", "Perda de um direito pelo seu não exercício prolongado, gerando em outrem a expectativa legítima (supressio) e o surgimento de direito correspondente (surrectio)."],
    ["Tu quoque", "Quem violou norma jurídica não pode exigir do outro o cumprimento da mesma norma."],
    ["Duty to mitigate the loss", "Dever do credor de evitar o agravamento do próprio prejuízo (Enunciado 169 do CJF)."],
    ["Abuso de direito", "Art. 187, CC: comete ato ilícito o titular que, ao exercer um direito, excede manifestamente os limites impostos pelo fim econômico ou social, pela boa-fé ou pelos bons costumes (critério objetivo-finalístico)."],
    ["Responsabilidade civil subjetiva", "Regra geral (art. 186 e 927, CC): exige conduta culposa, dano e nexo de causalidade."],
    ["Responsabilidade objetiva", "Art. 927, parágrafo único, CC: dispensa a culpa nos casos previstos em lei ou quando a atividade implicar risco para os direitos de outrem."],
    ["Reparação integral", "Art. 944, CC: a indenização mede-se pela extensão do dano, podendo o juiz reduzi-la equitativamente se houver excessiva desproporção entre gravidade da culpa e dano."],
    ["Princípio da prioridade (precedência) do registro", "Nos direitos reais imobiliários, a transmissão se opera com o registro; o título anterior prenotado tem preferência (art. 1.245, CC; Lei 6.015/73)."],
    ["Especialidade (publicidade) dos direitos reais", "O objeto do direito real deve ser individualizado e a constituição do direito, publicizada (registro ou tradição)."],
    ["Numerus clausus dos direitos reais", "Só a lei pode criar direitos reais; a lista do art. 1.225, CC é taxativa (tipicidade)."],
    ["Aderência (sequela) e oponibilidade erga omnes", "O direito real segue a coisa, oponível a todos."],
    ["Princípio da continuidade registral", "Cada registro deve ter ligação com o anterior, formando uma cadeia ininterrupta de titularidades."],
    ["Princípio da gravitação jurídica (acessório segue o principal)", "Art. 92, CC: o bem acessório segue a sorte do principal, salvo disposição em contrário."],
    ["Princípio da personalidade e dos direitos da personalidade", "Direitos intransmissíveis e irrenunciáveis, salvo exceções legais (art. 11, CC); proteção da integridade física, psíquica, nome, imagem, honra e privacidade."],
    ["Princípio da operabilidade na prescrição e decadência", "A prescrição atinge a pretensão (art. 189, CC) e a decadência o direito potestativo; prazos prescricionais só por lei (art. 192)."],
    ["Princípio da actio nata (teoria subjetiva)", "O prazo prescricional começa a correr quando o titular toma conhecimento da violação e de sua extensão."],
    ["Prevalência da vontade sobre a literalidade", "Prevalece a vontade real (declaração conforme a intenção) sobre a literalidade da linguagem (art. 112, CC)."],
    ["Princípio da irrepetibilidade", "O que se pagou espontaneamente em dívida de jogo ou obrigação natural não pode ser repetido (arts. 814 e 882, CC)."],
    ["Vedação ao enriquecimento sem causa", "Art. 884, CC: quem se enriquece à custa de outrem sem justa causa é obrigado a restituir o indevidamente auferido."],
    ["Teoria da imprevisão e onerosidade excessiva", "Arts. 317 e 478, CC: possibilidade de revisão ou resolução em caso de fatos extraordinários e imprevisíveis que tornem a prestação excessivamente onerosa."],
    ["Princípio da autonomia da vontade e liberdade de contratar", "Liberdade de contratar (se e com quem) e liberdade contratual (conteúdo), limitadas pela função social e pela boa-fé."],
    ["Pacta sunt servanda e rebus sic stantibus", "Dois polos: obrigatoriedade do pactuado versus revisão diante de alteração superveniente das circunstâncias."],
    ["Princípio da transparência nas relações contratuais", "Dever de informar adequadamente e de esclarecer o conteúdo do contrato, especialmente em contratos de adesão (art. 423, CC)."],
    ["Interpretação contra proferentem", "Cláusulas ambíguas ou contraditórias nos contratos de adesão são interpretadas a favor do aderente (arts. 423 e 424, CC)."],
  ]);

  add("Civil (Família)", [
    ["Dignidade da pessoa humana no direito de família", "Funda a proteção de todos os modelos familiares e dos direitos de cada membro (art. 1º, III, CF)."],
    ["Igualdade entre cônjuges e companheiros", "Art. 226, §5º, CF: direitos e deveres referentes à sociedade conjugal são exercidos igualmente pelo homem e pela mulher."],
    ["Igualdade entre os filhos", "Art. 227, §6º, CF e art. 1.596, CC: filhos havidos ou não da relação de casamento, ou por adoção, têm os mesmos direitos e qualificações, vedadas designações discriminatórias."],
    ["Pluralidade das entidades familiares", "A família não se limita ao casamento: união estável, família monoparental, homoafetiva e outras, reconhecidas pela Constituição e pelo STF (ADI 4277 e ADPF 132)."],
    ["Solidariedade familiar", "Dever de mútua assistência material e moral entre os membros da família; fundamento dos alimentos."],
    ["Afetividade", "O afeto como valor jurídico que fundamenta as relações familiares, inclusive a filiação socioafetiva (Tema 622 do STF)."],
    ["Melhor interesse da criança e do adolescente", "Todas as decisões que envolvam crianças e adolescentes devem priorizar seu interesse e bem-estar (art. 227, CF; ECA)."],
    ["Proteção integral", "Art. 227, CF e art. 1º do ECA: dever da família, da sociedade e do Estado de assegurar com absoluta prioridade os direitos da criança e do adolescente."],
    ["Paternidade responsável e planejamento familiar", "Art. 226, §7º, CF: decisão livre do casal, fundada na dignidade e na paternidade responsável, vedada coerção por instituições públicas ou privadas."],
    ["Intervenção mínima do Estado no direito de família", "O Estado deve respeitar a autonomia familiar, intervindo apenas para proteger direitos fundamentais e vulneráveis (art. 1.513, CC)."],
    ["Liberdade de constituir e dissolver a entidade familiar", "O casamento e a união estável podem ser desfeitos pela vontade das partes (divórcio sem prazo prévio ou causa; EC 66/2010)."],
    ["Monogamia", "Princípio estruturante do ordenamento familiar; impede, em regra, o reconhecimento de duas uniões estáveis simultâneas (Tema 529 do STF)."],
    ["Convivência familiar", "Direito da criança e do adolescente de ser criado no seio de sua família, excepcionalmente em família substituta (art. 19, ECA)."],
    ["Binômio necessidade-possibilidade nos alimentos", "Art. 1.694, §1º, CC: os alimentos são fixados na proporção das necessidades do alimentando e dos recursos do alimentante (acrescido da razoabilidade ou proporcionalidade)."],
    ["Irrepetibilidade e irrenunciabilidade dos alimentos", "Os alimentos pagos não são restituíveis e o direito aos alimentos não pode ser renunciado (art. 1.707, CC), embora seu exercício possa ser dispensado."],
    ["Reciprocidade dos alimentos", "O dever de prestar alimentos é recíproco entre parentes, cônjuges e companheiros (art. 1.696, CC)."],
    ["Guarda compartilhada como regra", "Art. 1.584, §2º, CC: salvo se um dos genitores declarar que não deseja a guarda, será aplicada a guarda compartilhada."],
    ["Princípio da comunhão plena de vida", "Art. 1.511, CC: o casamento estabelece comunhão plena de vida com base na igualdade de direitos e deveres dos cônjuges."],
    ["Autonomia patrimonial dos cônjuges (pacto antenupcial)", "Liberdade de escolha do regime de bens, que pode ser alterado mediante autorização judicial (art. 1.639, §2º, CC)."],
    ["Presunção pater is est", "Presumem-se concebidos na constância do casamento os filhos nascidos 180 dias após a convivência conjugal ou 300 dias após a dissolução (art. 1.597, CC); a presunção é relativa."],
    ["Verdade biológica e verdade socioafetiva", "A filiação pode decorrer de origem biológica ou de vínculo socioafetivo, sem hierarquia entre elas (Tema 622 do STF)."],
  ]);

  add("Civil (Sucessões)", [
    ["Saisine", "Art. 1.784, CC: aberta a sucessão, a herança transmite-se desde logo aos herdeiros legítimos e testamentários; a transmissão é imediata, sem intervalo."],
    ["Lei vigente à data da abertura da sucessão", "A sucessão e a legitimação para suceder regem-se pela lei em vigor ao tempo da abertura (art. 1.787, CC)."],
    ["Indivisibilidade da herança até a partilha", "Art. 1.791, CC: a herança defere-se como um todo unitário, ainda que vários sejam os herdeiros; direito indivisível, regido pelas normas do condomínio."],
    ["Intangibilidade da legítima", "Art. 1.846, CC: pertence aos herdeiros necessários, de pleno direito, metade dos bens da herança (legítima), que o testador não pode reduzir sem justa causa."],
    ["Pacta corvina (vedação de pactos sucessórios)", "Art. 426, CC: não pode ser objeto de contrato a herança de pessoa viva; exceção: partilha em vida (art. 2.018) e doação."],
    ["Liberdade de testar (limitada)", "Quem tiver herdeiros necessários só pode dispor de metade de seu patrimônio (porção disponível); testamento é negócio unilateral, personalíssimo, solene e revogável."],
    ["Favor testamenti (conservação do testamento)", "Na dúvida, interpreta-se o testamento de modo a preservar a vontade do testador e salvar a disposição (art. 1.899, CC)."],
    ["Igualdade na sucessão e ordem de vocação hereditária", "Descendentes, ascendentes, cônjuge e colaterais, nessa ordem, concorrendo o cônjuge/companheiro com descendentes e ascendentes (art. 1.829, CC; RE 646.721 e 878.694 do STF: equiparação entre cônjuge e companheiro)."],
    ["Princípio da representação e do direito de representação", "Na linha reta descendente, os filhos de herdeiro pré-morto, excluído ou indigno herdam por representação (art. 1.851, CC)."],
    ["Colação e igualdade das legítimas", "Os descendentes que receberam doação em vida devem trazê-la à colação para igualar as legítimas (art. 2.002, CC), salvo dispensa."],
    ["Princípio da irrenunciabilidade parcial / aceitação indivisível", "A aceitação ou renúncia da herança é irrevogável e indivisível (arts. 1.808 e 1.812, CC); não pode ser parcial, a termo ou condicional."],
  ]);

  add("Processo Civil", [
    ["Inércia da jurisdição (demanda)", "Art. 2º, CPC: o processo começa por iniciativa da parte e se desenvolve por impulso oficial, salvo exceções legais."],
    ["Dispositivo e impulso oficial", "As partes definem o objeto do litígio e dispõem de seus direitos; o juiz, após a provocação, conduz o processo."],
    ["Inafastabilidade da jurisdição", "Art. 3º, CPC: não se excluirá da apreciação jurisdicional ameaça ou lesão a direito, admitindo-se a arbitragem e a solução consensual dos conflitos."],
    ["Duração razoável do processo", "Art. 4º, CPC e art. 5º, LXXVIII, CF: as partes têm direito à solução integral do mérito, incluída a atividade satisfativa, em prazo razoável."],
    ["Boa-fé processual", "Art. 5º, CPC: quem de qualquer forma participa do processo deve comportar-se de acordo com a boa-fé."],
    ["Cooperação", "Art. 6º, CPC: todos os sujeitos do processo devem cooperar entre si para que se obtenha, em tempo razoável, decisão de mérito justa e efetiva."],
    ["Paridade de armas (isonomia processual)", "Art. 7º, CPC: assegura-se às partes paridade de tratamento em relação ao exercício de direitos e faculdades processuais, aos meios de defesa, aos ônus e aos deveres."],
    ["Contraditório substancial e vedação de decisão-surpresa", "Arts. 9º e 10, CPC: não se profere decisão contra uma parte sem ouvi-la e o juiz não pode decidir com base em fundamento sobre o qual as partes não tiveram oportunidade de se manifestar, ainda que matéria de ordem pública."],
    ["Publicidade e fundamentação das decisões", "Art. 11, CPC e 93, IX, CF: decisões fundamentadas, sob pena de nulidade; o art. 489, §1º, CPC lista hipóteses de decisão não fundamentada."],
    ["Ordem cronológica de conclusão", "Art. 12, CPC: os juízes e tribunais devem obedecer à ordem cronológica de conclusão para proferir sentença ou acórdão, com exceções do §2º."],
    ["Primazia (prioridade) do julgamento de mérito", "Art. 4º, CPC: preferência pela decisão de mérito sobre a extinção terminativa; fundamenta a sanabilidade de vícios (arts. 139, IX, e 317)."],
    ["Instrumentalidade das formas", "Art. 277 e 188, CPC: quando a lei prescrever determinada forma, o juiz considerará válido o ato que, realizado de outro modo, alcançar sua finalidade."],
    ["Princípio da economia processual", "Busca-se o máximo de resultado com o mínimo de atos processuais (ex.: aproveitamento de atos, cumulação de pedidos)."],
    ["Princípio do prejuízo (pas de nullité sans grief)", "Nenhum ato será declarado nulo se não houver prejuízo (art. 282, §1º, CPC)."],
    ["Princípio da congruência (adstrição ou correlação)", "Arts. 141 e 492, CPC: o juiz decide o mérito nos limites propostos pelas partes, sendo vedado julgar fora (extra), além (ultra) ou aquém (citra petita) do pedido."],
    ["Princípio da persuasão racional (livre convencimento motivado)", "Art. 371, CPC: o juiz apreciará a prova constante dos autos, indicando na decisão as razões da formação de seu convencimento."],
    ["Princípio da identidade física do juiz", "No CPC/2015 não é mais regra expressa; aplica-se de forma limitada (ex.: no processo penal, art. 399, §2º, CPP)."],
    ["Princípio do duplo grau de jurisdição", "Possibilidade de reexame da causa por órgão hierarquicamente superior; não é absoluto (ex.: causas de competência originária do STF)."],
    ["Taxatividade dos recursos", "Só são recursos os previstos em lei federal (art. 994, CPC)."],
    ["Singularidade (unirrecorribilidade)", "Contra cada decisão cabe, em regra, um único recurso por vez; admite exceções (ex.: recurso especial e extraordinário simultâneos)."],
    ["Fungibilidade recursal", "Admite-se a conversão de um recurso em outro quando presentes dúvida objetiva e ausência de erro grosseiro, observado o prazo do recurso correto."],
    ["Proibição da reformatio in pejus", "O recorrente não pode ter sua situação piorada em razão exclusiva do seu próprio recurso."],
    ["Dialeticidade recursal", "O recurso deve impugnar especificamente os fundamentos da decisão recorrida (art. 1.010, II e III, CPC)."],
    ["Efeito devolutivo e princípio tantum devolutum quantum appellatum", "A apelação devolve ao tribunal o conhecimento da matéria impugnada (art. 1.013, CPC), com profundidade ampla (§§1º e 2º)."],
    ["Princípio da demanda e adstrição na liquidação", "A liquidação não pode alterar a sentença liquidanda (art. 509, §4º, CPC)."],
    ["Autonomia da vontade no processo (negócios processuais)", "Art. 190, CPC: as partes podem estipular mudanças no procedimento e convencionar sobre seus ônus, poderes, faculdades e deveres processuais, em processos que admitam autocomposição."],
    ["Estabilidade, integridade e coerência da jurisprudência", "Arts. 926 e 927, CPC: os tribunais devem uniformizar sua jurisprudência e mantê-la estável, íntegra e coerente."],
    ["Efetividade da tutela jurisdicional", "O processo deve ser instrumento apto a realizar o direito material, com meios executivos adequados (art. 139, IV, e art. 536, CPC)."],
    ["Princípio da responsabilidade patrimonial", "Art. 789, CPC: o devedor responde com todos os seus bens presentes e futuros para o cumprimento de suas obrigações, salvo as restrições legais."],
    ["Princípio da menor onerosidade (execução menos gravosa)", "Art. 805, CPC: quando por vários meios o credor puder promover a execução, o juiz mandará que se faça pelo modo menos gravoso ao executado."],
    ["Princípio da execução específica", "Sempre que possível, o credor tem direito à satisfação in natura da obrigação, e não apenas a perdas e danos."],
    ["Princípio da tipicidade e atipicidade dos meios executivos", "A execução de pagar admite medidas típicas; o art. 139, IV, CPC autoriza medidas atípicas, mediante proporcionalidade."],
    ["Princípio da competência-competência", "O árbitro ou o juiz tem competência para decidir sobre sua própria competência (art. 8º, parágrafo único, da Lei 9.307/96)."],
    ["Perpetuatio jurisdictionis", "Art. 43, CPC: a competência é determinada no momento do registro ou distribuição da petição inicial, sendo irrelevantes as modificações de fato ou direito posteriores, salvo supressão do órgão ou alteração de competência absoluta."],
    ["Kompetenz-kompetenz da arbitragem e autonomia da cláusula compromissória", "A cláusula arbitral é autônoma em relação ao contrato; a nulidade do contrato não implica necessariamente a nulidade da cláusula."],
    ["Princípio da estabilização da demanda", "Após a citação, o autor não pode alterar o pedido ou a causa de pedir sem consentimento do réu (art. 329, CPC)."],
    ["Princípio da eventualidade", "O réu deve alegar toda a matéria de defesa na contestação (art. 336, CPC), sob pena de preclusão."],
    ["Preclusão", "Perda da faculdade de praticar ato processual por decurso do prazo (temporal), por prática anterior (consumativa) ou por incompatibilidade (lógica)."],
    ["Oralidade e concentração dos atos", "Predominância da palavra falada, com imediação do juiz com as provas e concentração dos atos em audiência."],
    ["Princípio da instrumentalidade e adequação do procedimento", "O procedimento deve adequar-se às peculiaridades da causa (art. 139, VI, CPC: dilação de prazos e inversão da produção de provas)."],
  ]);

  add("Penal", [
    ["Legalidade (reserva legal)", "Art. 5º, XXXIX, CF e art. 1º, CP: não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal."],
    ["Anterioridade da lei penal", "A lei penal incriminadora não pode retroagir; só a lei benéfica retroage (art. 5º, XL, CF)."],
    ["Taxatividade (lex certa)", "As leis penais devem ser claras e precisas, vedada a utilização de termos vagos que gerem insegurança."],
    ["Vedação à analogia in malam partem", "É vedada a analogia para prejudicar o réu; é admitida a analogia in bonam partem."],
    ["Irretroatividade da lei penal mais gravosa e retroatividade da benéfica (abolitio criminis e novatio legis in mellius)", "Art. 2º, CP: a lei posterior que favorece o agente retroage, ainda que a sentença tenha transitado em julgado."],
    ["Princípio da intervenção mínima (ultima ratio)", "O Direito Penal só deve atuar quando outros ramos do direito forem insuficientes para proteger o bem jurídico."],
    ["Fragmentariedade", "O Direito Penal protege apenas os bens jurídicos mais importantes contra as lesões mais graves."],
    ["Subsidiariedade", "A norma penal subsidiária só é aplicada quando não houver norma penal mais grave que absorva o fato."],
    ["Lesividade (ofensividade)", "Não há crime sem lesão ou perigo concreto de lesão ao bem jurídico de terceiro; veda a punição de pensamentos ou condutas meramente internas."],
    ["Insignificância (bagatela)", "Excludente de tipicidade material em fatos de mínima ofensividade, nenhuma periculosidade social, reduzido grau de reprovabilidade e inexpressividade da lesão (HC 84.412 do STF)."],
    ["Adequação social", "Condutas socialmente aceitas, mesmo formalmente típicas, não configuram crime (embora não revogue a lei por costume)."],
    ["Culpabilidade (nulla poena sine culpa)", "Não há pena sem culpabilidade; vedada responsabilidade penal objetiva."],
    ["Responsabilidade pessoal (intranscendência)", "Art. 5º, XLV, CF: nenhuma pena passará da pessoa do condenado; a obrigação de reparar e a perda de bens podem estender-se aos sucessores até o limite do patrimônio transferido."],
    ["Individualização da pena", "Art. 5º, XLVI, CF: a pena é individualizada em três momentos: legislativo (cominação), judicial (aplicação) e executório (cumprimento)."],
    ["Proporcionalidade da pena", "A pena deve ser proporcional à gravidade do crime e à culpabilidade; proíbe tanto o excesso quanto a proteção deficiente."],
    ["Humanidade das penas", "Art. 5º, XLVII, CF: vedadas penas de morte (salvo guerra declarada), perpétuas, de trabalhos forçados, de banimento e cruéis."],
    ["Ne bis in idem", "Ninguém pode ser punido ou processado duas vezes pelo mesmo fato (art. 8º, 4, da CADH)."],
    ["Presunção de inocência", "Art. 5º, LVII, CF: ninguém será considerado culpado até o trânsito em julgado da sentença penal condenatória."],
    ["Territorialidade (temperada)", "Art. 5º, CP: aplica-se a lei brasileira ao crime cometido no território nacional, sem prejuízo de convenções, tratados e regras de direito internacional."],
    ["Extraterritorialidade (incondicionada e condicionada)", "Art. 7º, CP: a lei brasileira aplica-se a crimes cometidos no exterior em hipóteses legais, algumas independentemente de condição (incondicionada) e outras sujeitas a requisitos."],
    ["Princípio da alteridade", "Ninguém pode ser punido por causar lesão exclusivamente a si mesmo (ex.: autolesão); o crime exige lesão a bem jurídico de outrem."],
    ["Princípio da confiança", "Quem age conforme o direito pode esperar que os demais também o façam; afasta imputação no âmbito do crime culposo."],
    ["Princípio da coculpabilidade", "Reconhece a corresponsabilidade do Estado pelas desigualdades sociais que influenciam a conduta delitiva (embora utilizado com cautela na jurisprudência)."],
    ["Princípio da continuidade normativa típica", "Mesmo com a revogação de um tipo, se a conduta continua criminosa em outro tipo, não há abolitio criminis."],
    ["Princípio da especialidade", "A norma especial afasta a geral (lex specialis derogat generali) no conflito aparente de normas."],
    ["Princípio da consunção (absorção)", "O crime-meio é absorvido pelo crime-fim quando sua prática é meio necessário ou normal fase de preparação ou execução."],
    ["Princípio da alternatividade", "Nos tipos mistos alternativos (múltiplas condutas), a prática de mais de um verbo, no mesmo contexto, configura crime único."],
    ["Princípio da imputação objetiva", "A imputação exige criação ou incremento de risco proibido, concretizado no resultado, dentro do âmbito de proteção da norma."],
    ["Princípio da exclusiva proteção de bens jurídicos", "O Direito Penal visa a tutelar bens jurídicos relevantes, não a moral ou a religião."],
  ]);

  add("Processo Penal", [
    ["Devido processo legal penal", "Ninguém será privado da liberdade ou de seus bens sem o devido processo legal (art. 5º, LIV, CF)."],
    ["Contraditório e ampla defesa", "Art. 5º, LV, CF: abrange defesa técnica obrigatória e autodefesa (interrogatório, presença);."],
    ["Presunção de inocência (não culpabilidade)", "Art. 5º, LVII, CF: regra de tratamento e regra probatória; o ônus da prova incumbe à acusação (art. 156, CPP)."],
    ["In dubio pro reo (favor rei)", "Havendo dúvida razoável, prevalece a solução mais favorável ao acusado; a condenação exige certeza (art. 386, VII, CPP)."],
    ["Nemo tenetur se detegere (não autoincriminação)", "Direito ao silêncio e de não produzir provas contra si (art. 5º, LXIII, CF); o silêncio não pode ser interpretado em prejuízo da defesa."],
    ["Sistema acusatório", "Separação das funções de acusar, defender e julgar (art. 129, I, CF); o juiz não inicia a persecução nem substitui a acusação (art. 3º-A do CPP, juiz das garantias)."],
    ["Juiz natural e imparcialidade", "Vedação a tribunais de exceção; o julgador deve ser independente e imparcial (art. 5º, XXXVII e LIII, CF)."],
    ["Juiz das garantias", "Arts. 3º-B a 3º-F do CPP (Lei 13.964/19): juiz responsável pelo controle da legalidade da investigação e pela salvaguarda dos direitos fundamentais do investigado (aplicação a partir de decisão do STF, ADI 6.298)."],
    ["Verdade real (substancial)", "No processo penal busca-se a reconstrução mais fiel possível dos fatos, embora limitada pelas provas ilícitas e pelo devido processo."],
    ["Inadmissibilidade de provas ilícitas", "Art. 5º, LVI, CF e art. 157, CPP: são inadmissíveis as provas obtidas por meios ilícitos; teoria dos frutos da árvore envenenada e exceções (fonte independente, descoberta inevitável)."],
    ["Obrigatoriedade da ação penal pública", "O MP deve oferecer denúncia presentes os elementos do art. 41 e ausentes as hipóteses de rejeição; mitigada pelo ANPP e pela transação penal."],
    ["Indisponibilidade da ação penal pública", "Art. 42, CPP: o MP não pode desistir da ação penal; o arquivamento exige decisão judicial/administrativa (art. 28)."],
    ["Oportunidade e disponibilidade (ação penal privada)", "O ofendido tem a faculdade de ajuizar a queixa e de, durante o processo, perdoar ou deixar de impulsionar (perempção)."],
    ["Indivisibilidade da ação penal privada", "Art. 48, CPP: a queixa contra qualquer dos autores do crime obrigará ao processo de todos."],
    ["Intranscendência", "A ação penal só pode ser proposta contra quem seja o suposto autor ou partícipe do crime."],
    ["Identidade física do juiz", "Art. 399, §2º, CPP: o juiz que presidiu a instrução deverá proferir a sentença, com exceções admitidas pela jurisprudência."],
    ["Publicidade", "Art. 93, IX, CF e art. 792, CPP: os atos processuais são públicos, salvo restrição para preservar a intimidade ou o interesse social."],
    ["Duração razoável do processo", "Art. 5º, LXXVIII, CF: garantia contra dilações indevidas; fundamenta o relaxamento de prisões excessivas."],
    ["Vedação à revisão pro societate", "A revisão criminal só é admitida em favor do réu (art. 621, CPP); a coisa julgada penal absolutória é, em regra, imutável."],
    ["Ne reformatio in pejus (direta e indireta)", "O tribunal não pode agravar a situação do réu quando só ele recorreu (art. 617, CPP)."],
    ["Favor libertatis e excepcionalidade da prisão preventiva", "A liberdade é a regra; a prisão cautelar é medida excepcional, subsidiária às medidas cautelares diversas (art. 282, §6º, CPP)."],
    ["Cautelaridade: fumus comissi delicti e periculum libertatis", "A prisão preventiva exige prova da existência do crime, indícios suficientes de autoria e perigo gerado pelo estado de liberdade (art. 312, CPP)."],
    ["Taxatividade dos recursos e voluntariedade", "Os recursos penais são, em regra, voluntários; a lei prevê o recurso de ofício em hipóteses específicas (ex.: art. 574, CPP)."],
    ["Princípio da correlação (congruência) entre acusação e sentença", "O juiz não pode condenar por fato diverso do descrito na denúncia sem mutatio libelli (art. 384, CPP); emendatio libelli no art. 383."],
    ["Princípio da livre apreciação da prova (persuasão racional)", "Art. 155, CPP: o juiz formará sua convicção pela livre apreciação da prova produzida em contraditório judicial, não podendo fundamentar a decisão exclusivamente nos elementos do inquérito."],
    ["Soberania dos veredictos", "Art. 5º, XXXVIII, «c», CF: no júri, a decisão dos jurados só pode ser reformada em hipóteses restritas (decisão manifestamente contrária à prova dos autos, apenas uma vez)."],
    ["Plenitude de defesa no júri", "Art. 5º, XXXVIII, «a», CF: no tribunal do júri assegura-se a plenitude da defesa, inclusive com argumentos extrajurídicos."],
    ["Sigilo das votações e competência do júri", "Art. 5º, XXXVIII, «b» e «d», CF: sigilo das votações e competência para os crimes dolosos contra a vida."],
    ["Princípio do estado de inocência e execução da pena", "Execução definitiva só após o trânsito em julgado (ADCs 43, 44 e 54 do STF), exceto condenação do júri em pena igual ou superior a 15 anos (Tema 1.068 do STF)."],
  ]);

  add("Consumidor", [
    ["Vulnerabilidade do consumidor", "Art. 4º, I, CDC: o consumidor é reconhecido como parte vulnerável (técnica, jurídica, fática ou informacional) na relação de consumo."],
    ["Hipossuficiência", "Condição de fragilidade processual ou econômica que justifica a inversão do ônus da prova (art. 6º, VIII, CDC)."],
    ["Boa-fé objetiva", "Art. 4º, III, CDC: harmonização dos interesses com base na boa-fé e no equilíbrio das relações."],
    ["Transparência", "Art. 4º, caput: informação clara e adequada sobre produtos e serviços, preço, riscos e demais dados relevantes (art. 31)."],
    ["Informação e dever de esclarecimento", "Art. 6º, III: informação adequada e clara sobre produtos e serviços, com especificação correta de quantidade, características, composição, qualidade, tributos incidentes e preço."],
    ["Equilíbrio contratual e vedação de cláusulas abusivas", "Art. 51, CDC: são nulas de pleno direito as cláusulas que estabeleçam obrigações iníquas ou abusivas, que coloquem o consumidor em desvantagem exagerada."],
    ["Interpretação mais favorável ao consumidor", "Art. 47, CDC: as cláusulas contratuais serão interpretadas de maneira mais favorável ao consumidor."],
    ["Vinculação da oferta", "Art. 30, CDC: toda informação ou publicidade suficientemente precisa veiculada obriga o fornecedor e integra o contrato."],
    ["Responsabilidade objetiva do fornecedor", "Arts. 12, 14 e 18 a 20: responsabilidade independente de culpa por vícios e defeitos de produtos e serviços; exceção: profissionais liberais (art. 14, §4º)."],
    ["Responsabilidade solidária", "Todos os fornecedores da cadeia de consumo respondem solidariamente pelos vícios e defeitos (arts. 7º, parágrafo único, 18 e 25, CDC)."],
    ["Inversão do ônus da prova", "Art. 6º, VIII: o juiz pode inverter o ônus em favor do consumidor, quando verossímil a alegação ou for ele hipossuficiente (ope judicis); no art. 38, é ope legis em publicidade."],
    ["Princípio da reparação integral dos danos", "Art. 6º, VI: direito à efetiva prevenção e reparação de danos patrimoniais e morais, individuais, coletivos e difusos."],
    ["Princípio da conservação do contrato", "Art. 51, §2º: a nulidade de uma cláusula não invalida o contrato, exceto se a ausência da cláusula acarretar ônus excessivo a qualquer das partes."],
    ["Princípio da boa-fé e vedação de publicidade enganosa e abusiva", "Arts. 36 a 38, CDC: a publicidade deve ser fácil e imediatamente identificada e não pode induzir o consumidor a erro, nem ser abusiva."],
    ["Princípio da proteção contratual (revisão por fato superveniente)", "Art. 6º, V: direito à modificação de cláusulas que estabeleçam prestações desproporcionais ou à sua revisão em razão de fatos supervenientes que as tornem excessivamente onerosas (sem exigir imprevisibilidade)."],
    ["Princípio do protecionismo do consumidor (ordem pública e interesse social)", "Art. 1º, CDC: as normas de proteção do consumidor são de ordem pública e interesse social; não podem ser afastadas pela vontade das partes."],
    ["Ação coletiva e tutela coletiva de consumo", "Arts. 81 a 104, CDC: direitos difusos, coletivos stricto sensu e individuais homogêneos, com legitimidade ativa ampla (MP, Defensoria, associações, entes públicos)."],
    ["Desconsideração da personalidade jurídica no CDC (teoria menor)", "Art. 28, §5º: basta que a personalidade jurídica seja obstáculo ao ressarcimento de prejuízos causados ao consumidor."],
  ]);

  add("Empresarial", [
    ["Livre iniciativa e livre concorrência", "Arts. 1º, IV, e 170, IV, CF: fundamentos da ordem econômica; permitem a atividade empresarial sob regulação para evitar abusos."],
    ["Função social da empresa", "A empresa deve cumprir finalidades sociais, gerando empregos, tributos e respeitando consumidores e meio ambiente (art. 170, CF e art. 47 da Lei 11.101/05)."],
    ["Preservação da empresa", "Art. 47, Lei 11.101/05: a recuperação judicial visa a viabilizar a superação da crise econômico-financeira, mantendo a fonte produtora, o emprego e os interesses dos credores."],
    ["Autonomia patrimonial da pessoa jurídica", "A pessoa jurídica não se confunde com seus sócios; os bens dos sócios respondem apenas nos casos legais ou na desconsideração (art. 49-A, CC)."],
    ["Desconsideração da personalidade jurídica (teoria maior)", "Art. 50, CC: exige abuso, caracterizado por desvio de finalidade ou confusão patrimonial; incidente processual nos arts. 133 a 137 do CPC."],
    ["Cartularidade", "O título de crédito é documento necessário para o exercício do direito nele mencionado (art. 887, CC)."],
    ["Literalidade", "Vale o que está escrito no título, nos limites do seu texto (art. 887, CC)."],
    ["Autonomia das obrigações cambiais", "Cada obrigação cambial é independente; os vícios de uma não contaminam as demais (art. 899, CC)."],
    ["Abstração", "Circulado o título, o devedor não pode opor ao terceiro de boa-fé exceções pessoais do portador anterior."],
    ["Inoponibilidade das exceções pessoais ao terceiro de boa-fé", "Art. 916, CC: as exceções fundadas em relação do devedor com portador anterior não são oponíveis ao portador de boa-fé."],
    ["Princípio par conditio creditorum", "Na falência, os credores da mesma classe devem ser tratados com igualdade, respeitada a ordem de classificação legal (art. 83, Lei 11.101/05)."],
    ["Princípio da maximização dos ativos (falência)", "Busca-se a realização célere e eficiente dos ativos para satisfazer o maior número de credores."],
    ["Princípio da soberania da assembleia de credores", "A assembleia geral decide sobre o plano de recuperação, sujeita ao controle de legalidade pelo juiz (e ao cram down do art. 58, §1º)."],
    ["Boa-fé e dever de lealdade na sociedade anônima", "Arts. 153 a 157 da Lei 6.404/76: os administradores devem empregar diligência, lealdade e informar, vedado o conflito de interesses."],
    ["Princípio majoritário e proteção das minorias", "Nas sociedades, as deliberações seguem a vontade da maioria, respeitado o direito de retirada, os direitos essenciais e a vedação ao abuso de poder."],
    ["Intangibilidade do capital social e do patrimônio", "O capital social é garantia dos credores; sua redução e a distribuição de lucros fictícios são regulados por lei."],
    ["Boa-fé na concorrência e proteção da propriedade industrial", "Lei 9.279/96: veda concorrência desleal e protege marcas, patentes e desenhos industriais (princípio da territorialidade e da especialidade da marca)."],
    ["Territorialidade e especialidade da marca", "A proteção da marca se limita ao território nacional e à classe de produtos ou serviços para a qual foi registrada (exceção: marca de alto renome, art. 125)."],
  ]);

  add("Tributário", [
    ["Legalidade tributária", "Art. 150, I, CF: é vedado exigir ou aumentar tributo sem lei que o estabeleça (reserva legal; exceções para alíquotas de II, IE, IPI, IOF e CIDE-combustíveis)."],
    ["Anterioridade anual", "Art. 150, III, «b»: veda cobrar tributos no mesmo exercício financeiro em que haja sido publicada a lei que os instituiu ou aumentou."],
    ["Anterioridade nonagesimal (noventena)", "Art. 150, III, «c»: veda cobrar tributos antes de decorridos 90 dias da publicação da lei que os instituiu ou aumentou (contribuições sociais: art. 195, §6º)."],
    ["Irretroatividade", "Art. 150, III, «a»: é vedado cobrar tributos em relação a fatos geradores ocorridos antes do início da vigência da lei que os houver instituído ou aumentado."],
    ["Isonomia tributária", "Art. 150, II: vedado tratamento desigual entre contribuintes que se encontrem em situação equivalente."],
    ["Capacidade contributiva", "Art. 145, §1º: sempre que possível, os impostos terão caráter pessoal e serão graduados segundo a capacidade econômica do contribuinte."],
    ["Vedação ao confisco", "Art. 150, IV: é vedado utilizar tributo com efeito de confisco; aplica-se também às multas tributárias."],
    ["Liberdade de tráfego", "Art. 150, V: vedado estabelecer limitações ao tráfego de pessoas ou bens por tributos interestaduais ou intermunicipais (ressalvado o pedágio)."],
    ["Uniformidade geográfica", "Art. 151, I: vedado à União instituir tributo que não seja uniforme em todo o território nacional ou que implique distinção ou preferência em relação a ente federado."],
    ["Não diferenciação tributária (de origem e destino)", "Art. 152: vedado estabelecer diferença tributária entre bens e serviços em razão de sua procedência ou destino."],
    ["Imunidade recíproca", "Art. 150, VI, «a»: entes federados não podem instituir impostos sobre patrimônio, renda ou serviços uns dos outros."],
    ["Seletividade e essencialidade", "O IPI será seletivo em função da essencialidade (art. 153, §3º, I); o ICMS poderá ser seletivo (art. 155, §2º, III)."],
    ["Não cumulatividade", "IPI, ICMS, IBS e CBS: compensa-se o que for devido em cada operação com o montante cobrado nas anteriores."],
    ["Progressividade", "O imposto de renda será informado pelos critérios da generalidade, universalidade e progressividade (art. 153, §2º, I)."],
    ["Princípio da praticabilidade e da simplicidade", "A tributação deve ser exequível, com procedimentos simples de apuração e arrecadação (reforma tributária, EC 132/2023)."],
    ["Indisponibilidade do crédito tributário", "A autoridade administrativa não pode dispensar o crédito tributário sem autorização legal (art. 141 do CTN)."],
    ["Estrita legalidade na exclusão do crédito (interpretação literal)", "Art. 111, CTN: interpreta-se literalmente a legislação tributária que disponha sobre suspensão ou exclusão do crédito, outorga de isenção e dispensa do cumprimento de obrigações acessórias."],
    ["Princípio da tipicidade tributária", "O fato gerador e demais elementos essenciais devem estar previstos de forma clara e específica na lei."],
    ["Princípio da vedação ao bis in idem e bitributação", "Evita-se que o mesmo ente tribute duas vezes o mesmo fato (bis in idem) ou que dois entes tribuam o mesmo fato (bitributação), salvo competência residual e extraordinária."],
    ["Princípio da transparência fiscal e da cooperação", "Art. 150, §5º: a lei determinará medidas para que os consumidores sejam esclarecidos acerca dos impostos incidentes sobre mercadorias e serviços."],
    ["Princípio da solidariedade no custeio da seguridade", "Art. 195, CF: financiamento por toda a sociedade, direta e indiretamente, mediante recursos orçamentários e contribuições sociais."],
  ]);

  add("Trabalho", [
    ["Proteção (tutelar)", "Princípio basilar do Direito do Trabalho: compensa a desigualdade econômica entre empregador e empregado com uma superioridade jurídica em favor do trabalhador; desdobra-se em in dubio pro operario, norma mais favorável e condição mais benéfica."],
    ["In dubio pro operario", "Na dúvida sobre a interpretação de uma norma, adota-se a que for mais favorável ao trabalhador (relativizado pela reforma trabalhista)."],
    ["Norma mais favorável", "Havendo mais de uma norma aplicável, aplica-se a mais benéfica ao trabalhador (art. 620 da CLT, na redação da Lei 13.467/17, faz prevalecer o acordo coletivo sobre a convenção coletiva)."],
    ["Condição mais benéfica", "As cláusulas contratuais mais vantajosas ao trabalhador incorporam-se ao contrato e não podem ser suprimidas (Súmula 51 do TST)."],
    ["Primazia da realidade", "Prevalecem os fatos concretos da relação sobre a forma ou os documentos (art. 9º da CLT)."],
    ["Irrenunciabilidade (indisponibilidade) de direitos", "O trabalhador não pode renunciar a direitos assegurados em lei; as normas de ordem pública são cogentes (art. 9º da CLT); mitigado em relação a direitos de indisponibilidade relativa e à transação com negociação coletiva (Tema 1.046 do STF)."],
    ["Continuidade da relação de emprego", "Presume-se que o contrato seja por prazo indeterminado; o ônus de provar a ruptura é do empregador (Súmula 212 do TST)."],
    ["Inalterabilidade contratual lesiva", "Art. 468, CLT: alterações nas condições de trabalho só são lícitas por mútuo consentimento e desde que não resultem em prejuízo ao empregado."],
    ["Intangibilidade salarial", "O salário é protegido contra descontos indevidos e retenções (arts. 462 e 463, CLT; art. 7º, X, CF)."],
    ["Irredutibilidade salarial", "Art. 7º, VI, CF: irredutibilidade do salário, salvo disposto em convenção ou acordo coletivo."],
    ["Alteridade", "O empregador assume os riscos do empreendimento (art. 2º, CLT); o empregado não responde pelo risco do negócio."],
    ["Não discriminação e igualdade salarial", "Art. 7º, XXX a XXXII, CF: proíbe diferença de salários, de exercício de funções e de critério de admissão por motivo de sexo, idade, cor ou estado civil; art. 461, CLT (equiparação salarial)."],
    ["Boa-fé objetiva no contrato de trabalho", "Os sujeitos do contrato devem agir com lealdade e probidade; o descumprimento pode justificar a justa causa ou a rescisão indireta."],
    ["Princípio da isonomia na terceirização e responsabilidade subsidiária", "O tomador responde subsidiariamente pelas obrigações trabalhistas da prestadora (Súmula 331 do TST; Lei 6.019/74)."],
    ["Princípio da razoabilidade e proporcionalidade na justa causa", "A penalidade deve ser proporcional à falta e aplicada de modo imediato, sem dupla punição (non bis in idem) e com nexo causal."],
    ["Princípio da intervenção mínima na autonomia coletiva", "Art. 611-A, CLT: a convenção ou acordo coletivo prevalece sobre a lei em hipóteses específicas; art. 8º, §3º: o Judiciário analisa apenas a conformidade dos elementos essenciais do negócio jurídico."],
    ["Princípio da proteção contra a despedida arbitrária", "Art. 7º, I, CF: relação de emprego protegida contra despedida arbitrária ou sem justa causa, nos termos de lei complementar (indenização compensatória)."],
    ["Princípio da dignidade do trabalhador e do valor social do trabalho", "Fundamento da República (art. 1º, III e IV, CF) e da ordem econômica (art. 170, caput)."],
  ], ALL);

  add("Processo do Trabalho", [
    ["Princípio da proteção processual", "Compensação da desigualdade material por regras processuais (ex.: gratuidade, jus postulandi, inversão do ônus da prova em alguns casos)."],
    ["Oralidade", "Predomínio da forma oral: reclamação verbal (art. 840, §2º, CLT), defesa oral em audiência (art. 847) e razões finais orais."],
    ["Informalidade e simplicidade", "Atos processuais com o mínimo de formalismo; reclamação por simples petição e jus postulandi nas varas e no TRT (Súmula 425 do TST)."],
    ["Celeridade e concentração dos atos", "Audiência una (art. 849, CLT); recursos sem efeito suspensivo (art. 899); irrecorribilidade imediata das decisões interlocutórias (art. 893, §1º)."],
    ["Conciliação", "Art. 764 e 846, CLT: os dissídios individuais ou coletivos submetidos à Justiça do Trabalho são sempre sujeitos à conciliação; o juiz deve empregar bons ofícios e persuasão."],
    ["Impulso oficial", "Na execução trabalhista, o juiz pode iniciar a execução de ofício (art. 878, CLT), com restrição quando a parte tem advogado."],
    ["Princípio da inversão do ônus da prova e aptidão para a prova", "Art. 818, CLT: o ônus incumbe ao reclamante quanto ao fato constitutivo e ao reclamado quanto aos impeditivos; o juiz pode redistribuir o ônus (§1º)."],
    ["Irrecorribilidade das decisões interlocutórias", "Art. 893, §1º, CLT: decisões interlocutórias só são impugnáveis no recurso da decisão definitiva, salvo exceções (Súmula 214 do TST)."],
    ["Princípio da subsidiariedade e supletividade do CPC", "Art. 15, CPC e 769, CLT: omissa a CLT e compatíveis as normas, aplica-se subsidiariamente o CPC (IN 39/2016 do TST)."],
    ["Princípio do protecionismo temperado e da sucumbência recíproca", "A reforma trabalhista (Lei 13.467/17) instituiu honorários de sucumbência e responsabilidade da parte pela perícia, mitigando o benefício da justiça gratuita (ADI 5.766)."],
    ["Efeito devolutivo em profundidade e transcendência", "O recurso de revista exige transcendência (art. 896-A, CLT), com critérios econômico, político, social e jurídico."],
  ], ALL);

  add("Ambiental", [
    ["Desenvolvimento sustentável", "Art. 225, caput e art. 170, VI, CF: atender às necessidades das gerações presentes sem comprometer as futuras."],
    ["Prevenção", "Perigo concreto e conhecido: devem ser adotadas medidas para evitar o dano ambiental (licenciamento, EIA/RIMA)."],
    ["Precaução", "Havendo ameaça de dano grave ou irreversível, a falta de certeza científica não deve ser utilizada como razão para postergar medidas de proteção (Declaração do Rio/92, Princípio 15)."],
    ["Poluidor-pagador", "O poluidor deve arcar com os custos da prevenção, da reparação e da repressão do dano (art. 225, §3º, CF e art. 4º, VII, da Lei 6.938/81)."],
    ["Usuário-pagador", "Quem usa recursos naturais deve pagar por sua utilização (ex.: cobrança pelo uso da água, Lei 9.433/97)."],
    ["Protetor-recebedor", "Quem protege o meio ambiente deve ser compensado ou incentivado (pagamento por serviços ambientais, Lei 14.119/21)."],
    ["Responsabilidade objetiva e integral por dano ambiental", "Art. 14, §1º, Lei 6.938/81: independe de culpa; teoria do risco integral (Tema 681 do STJ); solidariedade dos responsáveis e reparação in natura prioritária."],
    ["Princípio da participação (informação e educação ambiental)", "Art. 225, §1º, VI e VII: o Poder Público deve promover a educação ambiental e dar publicidade a informações; a coletividade tem direito de participar das decisões."],
    ["Função socioambiental da propriedade", "Art. 186, II, CF: a propriedade rural cumpre sua função social quando utiliza adequadamente os recursos naturais e preserva o meio ambiente."],
    ["Obrigação propter rem", "As obrigações ambientais, como a de recompor reserva legal, acompanham a propriedade, vinculando o adquirente (Súmula 623 do STJ)."],
    ["Princípio da vedação do retrocesso ecológico", "Proíbe a redução injustificada do nível de proteção ambiental já alcançado."],
    ["Princípio do limite (padrões ambientais)", "O Poder Público estabelece padrões de qualidade e emissão que limitam as atividades poluentes."],
    ["Princípio do equilíbrio ecológico e da ubiquidade", "O meio ambiente é bem de uso comum do povo (difuso) e deve ser considerado em todas as políticas públicas (art. 225, caput)."],
    ["Princípio do in dubio pro natura", "Na dúvida quanto à interpretação das normas ambientais ou à prova, decide-se em favor da proteção ambiental."],
    ["Princípio da cooperação entre os povos", "Art. 4º, IX, CF e acordos internacionais: cooperação para o progresso da humanidade e proteção ambiental global."],
    ["Princípio da natureza pública da proteção ambiental", "O meio ambiente ecologicamente equilibrado é direito fundamental de terceira geração, de titularidade transindividual."],
  ]);

  add("Eleitoral", [
    ["Anualidade (anterioridade eleitoral)", "Art. 16, CF: a lei que alterar o processo eleitoral entra em vigor na data da publicação, mas não se aplica à eleição que ocorra até um ano da data de sua vigência."],
    ["Soberania popular e sufrágio universal", "Art. 14, CF: a soberania popular é exercida pelo sufrágio universal e pelo voto direto e secreto, com valor igual para todos."],
    ["Voto como direito e dever", "O alistamento e o voto são obrigatórios para os maiores de 18 anos e facultativos para analfabetos, maiores de 70 e jovens de 16 e 17 anos."],
    ["Princípio da lisura (normalidade e legitimidade) das eleições", "Art. 14, §9º, CF: lei complementar protegerá a probidade administrativa, a moralidade e a normalidade e legitimidade das eleições contra a influência do poder econômico ou abuso do poder."],
    ["Igualdade de oportunidades entre candidatos", "Veda-se o uso da máquina pública, propaganda irregular e abuso do poder econômico ou político que desequilibrem o pleito (Lei 9.504/97)."],
    ["Princípio da celeridade processual eleitoral", "Os prazos são exíguos e contínuos, correndo em cartório ou secretaria (art. 7º, LC 64/90 e art. 16 da Lei 9.504/97)."],
    ["Princípio da preclusão eleitoral", "Prazos de interposição de recursos e impugnações são peremptórios e a preclusão é imediata."],
    ["Princípio da proporcionalidade (sistema)", "Nas eleições para a Câmara dos Deputados e casas legislativas, aplica-se o sistema proporcional de lista aberta, com quociente eleitoral e partidário."],
    ["Princípio da elegibilidade e inelegibilidade", "Requisitos do art. 14, §3º, CF e hipóteses de inelegibilidade na LC 64/90 (alterada pela LC 135/10 — Lei da Ficha Limpa)."],
    ["Princípio da identidade partidária e fidelidade", "O mandato pertence ao partido nas eleições proporcionais (STF, MS 26.602, 26.603 e 26.604); a infidelidade pode gerar perda do mandato, salvo justa causa."],
    ["Princípio da reserva de gênero", "Art. 10, §3º, Lei 9.504/97: cada partido preencherá o mínimo de 30% e o máximo de 70% para candidaturas de cada sexo; fraude gera cassação (Súmula 73 do TSE)."],
    ["Princípio da liberdade de propaganda e limitações", "A propaganda eleitoral é permitida após 16 de agosto (art. 36), vedadas a propaganda antecipada e a propaganda paga na imprensa fora dos limites legais."],
  ]);

  add("ECA", [
    ["Proteção integral", "Art. 1º: o ECA dispõe sobre a proteção integral à criança (até 12 anos incompletos) e ao adolescente (12 a 18 anos); art. 3º assegura todos os direitos fundamentais."],
    ["Prioridade absoluta", "Art. 4º e art. 227, CF: primazia em receber proteção e socorro, precedência no atendimento, preferência na formulação e execução de políticas públicas e destinação privilegiada de recursos."],
    ["Melhor interesse da criança", "Critério orientador do aplicador do direito e do legislador em todas as decisões que envolvam menores."],
    ["Condição peculiar de pessoa em desenvolvimento", "Arts. 6º e 100: crianças e adolescentes devem ser tratados considerando sua condição peculiar; fundamento das medidas protetivas e socioeducativas."],
    ["Municipalização do atendimento", "Art. 88, I: a política de atendimento deve priorizar a municipalização, com participação dos conselhos tutelares e dos conselhos de direitos."],
    ["Intervenção precoce e mínima", "Art. 100, parágrafo único, VI e VII: a intervenção deve ser exercida pelas autoridades e instituições cuja ação seja indispensável, de modo precoce e mínimo."],
    ["Responsabilidade parental", "Art. 100, IX: a pais ou responsável incumbe o dever de promover a educação e cuidado, assegurando a proteção da criança e do adolescente."],
    ["Excepcionalidade e brevidade da medida de internação", "Art. 121: a internação está sujeita aos princípios da brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento."],
    ["Escuta especializada e depoimento especial", "Lei 13.431/17: crianças e adolescentes vítimas ou testemunhas de violência têm direito a procedimentos protetivos, evitando a revitimização."],
    ["Convivência familiar e comunitária", "Art. 19: toda criança tem direito a ser criada e educada no seio de sua família e, excepcionalmente, em família substituta; o acolhimento institucional é medida provisória e excepcional."],
    ["Princípio da legalidade e da individualização das medidas socioeducativas", "Medidas socioeducativas só podem ser aplicadas por ato infracional previsto em lei e devem ser proporcionais à capacidade do adolescente de cumpri-las (art. 112, §1º)."],
  ], ["oab", "mpsc", "magsc", "magfed"]);

  add("Ética (OAB)", [
    ["Independência profissional", "O advogado deve preservar sua liberdade e independência, não se subordinando a interesses do cliente ou de terceiros contrários à lei (art. 31, EOAB e art. 2º, CED)."],
    ["Inviolabilidade e sigilo profissional", "O sigilo profissional é de ordem pública e independe de solicitação do cliente (art. 36 do CED); o advogado pode, excepcionalmente, revelá-lo para a própria defesa em grave ameaça."],
    ["Lealdade e boa-fé", "O advogado deve proceder com lealdade e boa-fé, evitando condutas que induzam a erro ou prejudiquem a parte contrária (arts. 2º, VIII e 6º, CED)."],
    ["Probidade e decoro", "O advogado deve atuar com honestidade, probidade, discrição e urbanidade no exercício da profissão e fora dela."],
    ["Dignidade da advocacia", "O advogado deve zelar pelo prestígio da classe e pela boa imagem da advocacia (art. 2º, parágrafo único, CED)."],
    ["Vedação da mercantilização", "A publicidade profissional deve ter caráter meramente informativo e primar pela discrição e sobriedade, sem captação de clientela (arts. 39 a 47 do CED; Provimento 205/2021)."],
    ["Livre exercício e inviolabilidade do advogado", "Art. 2º, §3º, EOAB: no exercício da profissão, o advogado é inviolável por seus atos e manifestações, nos limites da lei."],
    ["Indispensabilidade do advogado à administração da justiça", "Art. 133, CF e art. 2º, EOAB: o advogado é indispensável à administração da justiça, ressalvadas as exceções (habeas corpus, juizados em causas de até 20 s.m., JT)."],
    ["Imunidade profissional", "Art. 7º, §2º, EOAB: o advogado tem imunidade profissional, não constituindo injúria ou difamação puníveis qualquer manifestação de sua parte no exercício da atividade, em juízo ou fora dele."],
    ["Princípio da autonomia dos honorários", "Os honorários contratados, de sucumbência e arbitrados são devidos ao advogado; o contrato escrito é recomendável (art. 48 e ss., CED)."],
    ["Dever de informação e esclarecimento ao cliente", "O advogado deve informar o cliente, de forma clara e inequívoca, quanto a eventuais riscos da demanda e das consequências de sua pretensão (art. 9º, CED)."],
    ["Incompatibilidade e impedimento", "A advocacia é incompatível com certos cargos (art. 28, EOAB) e impedida em relação a outros (art. 30); a incompatibilidade proíbe, o impedimento restringe."],
        ["Vedação ao patrocínio infiel", "O advogado não pode trair a confiança do cliente prejudicando interesse a ele confiado (art. 355 do CP e art. 34 do EOAB: infração disciplinar)."],
  ], ["oab"]);

  add("Direitos Humanos", [
    ["Universalidade", "Os direitos humanos pertencem a todas as pessoas, independentemente de nacionalidade, sexo, religião ou condição."],
    ["Indivisibilidade e interdependência", "Os direitos civis, políticos, econômicos, sociais e culturais formam um conjunto inseparável (Conferência de Viena, 1993)."],
    ["Imprescritibilidade, inalienabilidade e irrenunciabilidade", "Características dos direitos humanos: não se perdem pelo decurso do tempo, não podem ser transferidos e não se renunciam."],
    ["Princípio pro persona (pro homine)", "Em caso de conflito entre normas, aplica-se a que melhor proteja a pessoa, seja interna ou internacional."],
    ["Proibição do retrocesso (progressividade)", "Os Estados devem avançar progressivamente na efetivação dos direitos econômicos, sociais e culturais, vedando medidas regressivas injustificadas."],
    ["Controle de convencionalidade", "Obrigação de os juízes e tribunais internos verificarem a compatibilidade das leis com os tratados de direitos humanos (Corte IDH, Almonacid Arellano vs. Chile; CNJ, Recomendação 123/2022)."],
    ["Primazia da norma mais favorável", "Art. 29, «b», da CADH: nenhuma disposição da Convenção pode ser interpretada no sentido de limitar o gozo de direitos reconhecidos por lei interna ou outra convenção."],
    ["Princípio da subsidiariedade (complementaridade)", "A jurisdição internacional só é acionada após esgotados os recursos internos (art. 46 da CADH), ressalvadas exceções."],
    ["Princípio da proibição de tortura e tratamento desumano", "Norma de jus cogens: inderrogável, mesmo em estado de emergência (art. 5º da CADH; Convenção contra a Tortura)."],
    ["Dignidade da pessoa humana e núcleo essencial", "Fundamento de todos os direitos humanos; o conteúdo mínimo dos direitos não pode ser violado."],
    ["Efeito útil (effet utile)", "Os tratados de direitos humanos devem ser interpretados de modo a conferir-lhes plena eficácia prática."],
    ["Estatuto supralegal dos tratados de direitos humanos", "Tratados de direitos humanos não aprovados com o quórum do art. 5º, §3º, têm status supralegal (STF, RE 466.343); os aprovados com quórum qualificado têm status de emenda constitucional."],
  ]);

  add("Previdenciário", [
    ["Solidariedade", "Art. 195, CF: financiamento por toda a sociedade; as contribuições dos ativos custeiam os benefícios dos inativos (regime de repartição)."],
    ["Universalidade da cobertura e do atendimento", "Art. 194, parágrafo único, I: a seguridade social protege todas as pessoas e todos os riscos sociais."],
    ["Uniformidade e equivalência dos benefícios rurais e urbanos", "Art. 194, II: tratamento igualitário entre trabalhadores urbanos e rurais."],
    ["Seletividade e distributividade", "Art. 194, III: o legislador escolhe os riscos cobertos (seletividade) e os beneficiários que mais precisam (distributividade)."],
    ["Irredutibilidade do valor dos benefícios", "Art. 194, IV: o valor nominal dos benefícios não pode ser reduzido; a atualização preserva o valor real (art. 201, §4º)."],
    ["Equidade na forma de participação no custeio", "Art. 194, V: o custeio é equitativo, de acordo com a capacidade contributiva."],
    ["Diversidade da base de financiamento", "Art. 194, VI: o custeio da seguridade tem diversas fontes (contribuições e recursos orçamentários)."],
    ["Caráter democrático e descentralizado da gestão", "Art. 194, VII: gestão quadripartite com participação dos trabalhadores, empregadores, aposentados e governo."],
    ["Preexistência do custeio em relação ao benefício (regra da contrapartida)", "Art. 195, §5º: nenhum benefício ou serviço da seguridade social poderá ser criado, majorado ou estendido sem a correspondente fonte de custeio total."],
    ["Equilíbrio financeiro e atuarial", "Art. 201, caput: o RGPS observará critérios que preservem o equilíbrio financeiro e atuarial."],
    ["Tempus regit actum", "O benefício previdenciário é regido pela lei vigente ao tempo em que preenchidos os requisitos (ex.: Súmula 340 do STJ, pensão por morte; Súmula 359 do STF)."],
    ["Princípio da contributividade", "O RGPS tem caráter contributivo e filiação obrigatória (art. 201, caput)."],
    ["Princípio do in dubio pro misero", "Em matéria previdenciária e assistencial, a prova é analisada de forma a favorecer o segurado (flexibilização probatória, especialmente do trabalhador rural)."],
  ], ["oab", "magfed"]);

  add("Financeiro", [
    ["Legalidade orçamentária", "O orçamento deve ser aprovado por lei (PPA, LDO e LOA) e não pode haver despesa sem prévia autorização (art. 165, CF)."],
    ["Unidade e universalidade orçamentárias", "Cada ente deve ter um só orçamento (unidade) que compreenda todas as receitas e despesas (universalidade)."],
    ["Anualidade (periodicidade)", "A LOA tem vigência de um exercício financeiro (art. 34 da Lei 4.320/64), coincidente com o ano civil."],
    ["Exclusividade", "Art. 165, §8º: a LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa (exceções: autorização para créditos suplementares e operações de crédito)."],
    ["Não afetação das receitas de impostos", "Art. 167, IV: veda a vinculação de receita de impostos a órgão, fundo ou despesa, ressalvadas as exceções constitucionais (saúde, educação, etc.)."],
    ["Responsabilidade fiscal", "LRF (LC 101/2000): gestão fiscal responsável com planejamento, transparência, controle e equilíbrio das contas públicas."],
    ["Equilíbrio orçamentário", "Previsões de receita e despesa devem se equilibrar; a regra de ouro (art. 167, III) veda operações de crédito superiores às despesas de capital."],
    ["Transparência fiscal", "Divulgação ampla de planos, orçamentos, relatórios de gestão fiscal e prestação de contas (arts. 48 e 48-A, LRF)."],
  ]);

  add("Internacional", [
    ["Soberania e igualdade entre os Estados", "Fundamentos da Carta da ONU (art. 2º, 1): os Estados são formalmente iguais em direitos e deveres."],
    ["Pacta sunt servanda no direito dos tratados", "Art. 26 da Convenção de Viena: todo tratado em vigor obriga as partes e deve ser cumprido de boa-fé."],
    ["Não intervenção e autodeterminação dos povos", "Art. 4º, III e IV, CF: princípios das relações internacionais do Brasil."],
    ["Prevalência dos direitos humanos nas relações internacionais", "Art. 4º, II, CF: a República Federativa do Brasil rege-se, nas relações internacionais, pela prevalência dos direitos humanos."],
    ["Solução pacífica dos conflitos", "Art. 4º, VII, CF e Carta da ONU: os Estados devem resolver suas controvérsias por meios pacíficos."],
    ["Cooperação entre os povos para o progresso da humanidade", "Art. 4º, IX, CF: fundamento da integração latino-americana (art. 4º, parágrafo único)."],
    ["Pacta tertiis nec nocent nec prosunt", "Art. 34 da Convenção de Viena: um tratado não cria obrigações nem direitos para terceiros sem seu consentimento."],
    ["Estoppel e boa-fé no direito internacional", "Os Estados não podem agir contra a conduta anterior que gerou confiança em outros Estados."],
    ["Princípio da jurisdição universal e do aut dedere aut judicare", "Certos crimes internacionais (genocídio, tortura, pirataria) podem ser julgados por qualquer Estado, ou o suspeito deve ser extraditado."],
    ["Princípio da dupla incriminação (extradição)", "A extradição só é concedida se o fato for crime tanto no Estado requerente quanto no requerido (Lei 13.445/17)."],
    ["Princípio da especialidade (extradição)", "O extraditado só pode ser julgado pelo crime que fundamentou o pedido de extradição."],
    ["Non-refoulement", "Proibição de devolver o refugiado ou solicitante de refúgio a território onde sua vida ou liberdade esteja ameaçada (Convenção de 1951 e Lei 9.474/97)."],
  ], ["magfed"]);

  add("Constitucional", [
    ["Obrigatoriedade da lei (ninguém se escusa de cumpri-la)", "A lei só obriga após ser publicada; ninguém se escusa de cumpri-la alegando que não a conhece (art. 3º, LINDB)."],
    ["Princípio da segurança jurídica", "Proteção do direito adquirido, do ato jurídico perfeito e da coisa julgada (art. 5º, XXXVI, CF)."],
    ["Princípio da proteção da confiança legítima", "Os administrados podem confiar na estabilidade das situações e na coerência da atuação estatal."],
    ["Princípio da vedação ao excesso e à proteção deficiente", "O Estado não pode agir de forma excessiva ao restringir direitos nem de forma insuficiente ao protegê-los."],
    ["Princípio da proibição de tribunais de exceção e juiz natural", "Art. 5º, XXXVII: não haverá juízo ou tribunal de exceção."],
    ["Princípio da liberdade", "Art. 5º, caput e II: a liberdade é regra; restrições só por lei e para proteger outros direitos ou interesses constitucionais."],
    ["Princípio da inviolabilidade do domicílio", "Art. 5º, XI: a casa é asilo inviolável; só se entra com consentimento, em flagrante delito, desastre, para prestar socorro ou, durante o dia, por determinação judicial."],
    ["Princípio do sigilo das comunicações", "Art. 5º, XII: inviolável o sigilo da correspondência, das comunicações telegráficas, de dados e das telefônicas (esta última, por ordem judicial para fins penais)."],
    ["Princípio da irretroatividade da lei (direito adquirido)", "A lei nova respeita o direito adquirido, o ato jurídico perfeito e a coisa julgada; não há direito adquirido a regime jurídico (STF)."],
    ["Princípio da não ingerência (autonomia das entidades federativas)", "Os entes federativos exercem suas competências sem ingerência indevida uns dos outros; a intervenção é excepcional (arts. 34 e 35, CF)."],
    ["Princípio da predominância do interesse", "A repartição de competências federativas obedece ao interesse predominante: nacional (União), regional (Estados) e local (Municípios)."],
    ["Princípio da subsidiariedade na federação", "Prefere-se a atuação do ente mais próximo do cidadão, salvo quando a União for mais eficiente."],
    ["Princípio do pacto federativo e da cooperação (competência concorrente)", "Art. 24, CF: União edita normas gerais; Estados suplementam; competências comuns do art. 23 exigem cooperação (LC 140/2011)."],
    ["Pertinência temática (legitimados especiais)", "No controle concentrado, Mesas de Assembleia Legislativa, Governadores, confederações sindicais e entidades de classe de âmbito nacional devem demonstrar relação entre sua finalidade e a norma impugnada (art. 103, CF); os demais legitimados são universais."],
    ["Princípio da causa de pedir aberta no controle abstrato", "O STF não está vinculado aos fundamentos jurídicos invocados na petição inicial, mas está vinculado ao pedido (princípio da congruência)."],
    ["Princípio da reserva de plenário (full bench)", "Art. 97, CF: somente pelo voto da maioria absoluta dos membros do tribunal ou do órgão especial os tribunais podem declarar a inconstitucionalidade de lei (Súmula Vinculante 10)."],
    ["Princípio da legalidade orçamentária e das despesas públicas", "Nenhuma despesa pode ser realizada sem previsão orçamentária (art. 167, CF)."],
    ["Princípio da transparência e da prestação de contas", "Art. 70, parágrafo único, CF: prestará contas qualquer pessoa que utilize, arrecade, guarde, gerencie ou administre dinheiros públicos."],
  ]);
})();
